// GinServerOptions provides options for the Gin server.
type GinServerOptions struct {
	BaseURL      string
	Middlewares  []MiddlewareFunc
	ErrorHandler func(*gin.Context, error, int)
}

// RegisterHandlers creates http.Handler with routing matching OpenAPI spec.
func RegisterHandlers(router gin.IRouter, si ServerInterface) {
	RegisterHandlersWithOptions(router, si, GinServerOptions{})
}

// RegisterHandlersWithOptions creates http.Handler with additional options
func RegisterHandlersWithOptions(router gin.IRouter, si ServerInterface, options GinServerOptions) {
	errorHandler := options.ErrorHandler
	if errorHandler == nil {
		errorHandler = func(c *gin.Context, err error, statusCode int) {
			c.JSON(statusCode, gin.H{"msg": err.Error()})
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandler:       errorHandler,
	}

	router.GET(options.BaseURL+"/ping", wrapper.Ping)
	router.GET(options.BaseURL+"/config", wrapper.GetConfig)
	router.POST(options.BaseURL+"/config", wrapper.SetConfig)
	router.GET(options.BaseURL+"/browse", wrapper.Browse)
	router.GET(options.BaseURL+"/audio/scan", wrapper.ScanAudio)
	router.GET(options.BaseURL+"/audio/search", wrapper.SearchAudio)
	router.DELETE(options.BaseURL+"/audio/delete", wrapper.DeleteAudio)
	router.POST(options.BaseURL+"/audio/restore", wrapper.RestoreAudio)
	router.POST(options.BaseURL+"/audio/update", wrapper.UpdateAudio)
	router.GET(options.BaseURL+"/audio/recyclebin", wrapper.GetRecycleBin)
	router.GET(options.BaseURL+"/audio/source", wrapper.GetAudioSource)
	router.POST(options.BaseURL+"/audio/upload", wrapper.UploadAudio)
	router.POST(options.BaseURL+"/audio/lyric/upload", wrapper.UploadLyric)
	router.GET(options.BaseURL+"/audio/scrape", wrapper.ScrapeAudio)
	router.GET(options.BaseURL+"/audio/lyric/fetch", wrapper.FetchLyric)
	router.GET(options.BaseURL+"/audio/lyric/source", wrapper.GetLyricSource)
	router.POST(options.BaseURL+"/sync/test-connection", wrapper.SyncTestConnection)
	router.GET(options.BaseURL+"/sync/browse", wrapper.SyncBrowse)
	router.POST(options.BaseURL+"/sync/compare", wrapper.SyncCompare)
	router.POST(options.BaseURL+"/sync/execute", wrapper.SyncExecute)
	router.GET(options.BaseURL+"/image/scan", wrapper.ScanImage)
	router.GET(options.BaseURL+"/image/search", wrapper.SearchImage)
	router.GET(options.BaseURL+"/image/source", wrapper.GetImageSource)
	router.GET(options.BaseURL+"/image/thumb", wrapper.GetImageThumb)
	router.GET(options.BaseURL+"/image/recyclebin", wrapper.GetImageRecycleBin)
	router.DELETE(options.BaseURL+"/image/delete", wrapper.DeleteImage)
	router.POST(options.BaseURL+"/image/restore", wrapper.RestoreImage)
	router.GET(options.BaseURL+"/video/scan", wrapper.ScanVideo)
	router.GET(options.BaseURL+"/video/search", wrapper.SearchVideo)
	router.GET(options.BaseURL+"/video/source", wrapper.GetVideoSource)
	router.GET(options.BaseURL+"/video/thumb", wrapper.GetVideoThumb)
	router.GET(options.BaseURL+"/video/recyclebin", wrapper.GetVideoRecycleBin)
	router.DELETE(options.BaseURL+"/video/delete", wrapper.DeleteVideo)
	router.POST(options.BaseURL+"/video/restore", wrapper.RestoreVideo)
}
